using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// With the default reflection resolver, any type is resolvable:
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded — type: {found!.Type.Name}");
}

// With a custom resolver that resolves *nothing*, the probe returns false
// instead of throwing:
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            static ti =>
            {
                // Reject every type by marking it as unsupported
                if (ti.Type == typeof(Order))
                    throw new NotSupportedException("Order not allowed");
            }
        }
    }
};

if (restrictedOptions.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
{
    Console.WriteLine($"Order metadata resolved: {orderInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Order> returned false — no exception thrown");
}

// Records used by the demo
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

