     Console.WriteLine($"TryGetTypeInfo<Person> succeeded — type: {found!.Type.Name}");
 }

 // With a resolver that only handles Person (returns null for everything else),
 // TryGetTypeInfo returns false instead of throwing:
 var restrictedOptions = new JsonSerializerOptions
 {
     TypeInfoResolver = JsonTypeInfoResolver.Combine(
         new PersonOnlyResolver()
     )
 };

 if (restrictedOptions.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
 {
     Console.WriteLine($"Order metadata resolved: {orderInfo!.Type.Name}");
 }
 else
 {
     Console.WriteLine("TryGetTypeInfo<Order> returned false — no exception thrown");
 }

 // Records used by the demo
 public record Person(string Name, int Age);
 public record Order(int Id, decimal Total);

 // A resolver that only knows about Person — returns null for anything else
 public class PersonOnlyResolver : IJsonTypeInfoResolver
 {
     private readonly DefaultJsonTypeInfoResolver _inner = new();

     public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
         => type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
 }
